(5924134, 863825, 77196, '<td valign="top">The shoes get a bit lost in the shadow of the tree. Made me smile. Also nice that it is in B&amp;W.</td>', 'The shoes get a bit lost in the shadow of the tree. Made me smile. Also nice that it is in B&W.', '2010-03-31 22:12:33.000000', NULL, 1),
(5924291, 863967, 60495, '<td valign="top">What an awesome sight, love the way it was captured. What can I say it is a 10!</td>', 'What an awesome sight, love the way it was captured. What can I say it is a 10!', '2010-04-01 00:15:09.000000', NULL, 1),
